use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;
use std::io::{self, BufWriter, Write};

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLING_SECONDS: i64 = 30 * 60;

#[derive(Debug, PartialEq, Eq)]
pub struct InvoiceProject {
    pub name: String,
    pub billable_seconds: i64,
}

fn invoice_duration_seconds(duration: i64) -> i64 {
    let duration = duration.max(0);
    let rounded = ((duration + BILLING_INCREMENT_SECONDS - 1) / BILLING_INCREMENT_SECONDS)
        * BILLING_INCREMENT_SECONDS;
    rounded.max(MINIMUM_BILLING_SECONDS)
}

pub fn summarize_entries(entries: &[TimeEntry]) -> Vec<InvoiceProject> {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries {
        if entry.billable && entry.stop.is_some() {
            let project = entry
                .project
                .as_ref()
                .map(|project| project.name.clone())
                .unwrap_or_else(|| "No Project".to_string());
            *totals.entry(project).or_default() += invoice_duration_seconds(entry.duration);
        }
    }

    let mut projects = totals
        .into_iter()
        .map(|(name, billable_seconds)| InvoiceProject {
            name,
            billable_seconds,
        })
        .collect::<Vec<_>>();
    projects.sort_by(|left, right| {
        right
            .billable_seconds
            .cmp(&left.billable_seconds)
            .then_with(|| left.name.cmp(&right.name))
    });
    projects
}

pub struct InvoiceCommand;

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let projects = summarize_entries(&entries);
        let mut output = BufWriter::new(io::stdout());

        if projects.is_empty() {
            writeln!(output, "(no data)").expect("failed to print");
            return Ok(());
        }

        let total = projects
            .iter()
            .map(|project| project.billable_seconds)
            .sum::<i64>();
        for project in projects {
            writeln!(output, "{}s  {}", project.billable_seconds, project.name)
                .expect("failed to print");
        }
        writeln!(output, "{total}s  Total").expect("failed to print");
        Ok(())
    }
}

